import sys

sys.setrecursionlimit(10**7)

mod = 998244353

def go(A, i, pv, v, dp):
    if i == len(A):
        return 1 if pv == 0 else 0
    if dp[i][pv][v] != -1:
        return dp[i][pv][v]
    ans = 0
    if A[i] == '_':
        for j in range(10):
            if i == 0 and j == 0:
                continue
            y = (pv * 10 + j) % 25
            ans += go(A, i + 1, y, v, dp)
    elif A[i] == 'X':
        if v != 10:
            ans += go(A, i + 1, (pv * 10 + v) % 25, v, dp)
        else:
            for j in range(10):
                if i == 0 and j == 0:
                    continue
                y = (pv * 10 + j) % 25
                ans += go(A, i + 1, y, j, dp)
    else:
        digit = int(A[i])
        ans += go(A, i + 1, (pv * 10 + digit) % 25, v, dp)
    dp[i][pv][v] = ans
    return ans

def main():
    input_str = sys.stdin.readline().strip()
    A = list(input_str)
    if len(A) == 1 and A[0] == '0':
        print(1)
        return
    if A[0] == '0':
        print(0)
        return
    if len(A) == 1 and (A[0] == 'X' or A[0] == '_'):
        print(1)
        return
    dp = [[[ -1 for _ in range(11)] for _ in range(25)] for _ in range(len(A)+1)]
    print(go(A, 0, 0, 10, dp))

if __name__ == "__main__":
    main()

